using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]   // 5%: 249.95 floored to 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]   // 50.00 enters +1 band
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)] // 6% of 19999 = 1199.94 -> 1199
    [InlineData(LoyaltyTier.Green, 20_000, 16_000 + 0)]
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]
    [InlineData(LoyaltyTier.Gold, 5_000, 4_600)]
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]  // 10% reached
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10% cap
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12 capped to 10
    [InlineData(LoyaltyTier.Green, 99, 95)]          // 4.95 floored to 4
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var actual = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, actual);
    }
}
E
